def replace(file, defs, limit)
  text = File.read(file); n = 0
  text.scan(/^\\medterm\{[^}]+\} .*?(?=^\\medterm\{|\z)/m).each do |b|
    break if n >= limit; next unless b.match?(MARKER)
    t = b[/^\\medterm\{([^}]+)\}/, 1]; next unless defs.key?(t)
    text = text.sub(b, "\\medterm{#{t}} #{defs[t]}\n\n"); n += 1
  end
  File.write(file, text); n
end
